const link=(text,path,cls='')=>`<a class="${cls}" href="#${path}">${text}</a>`;
const button=(text,action,id='',cls='')=>`<button class="${cls}" data-action="${action}" data-id="${esc(id)}">${text}</button>`;
const badge=(text,cls='')=>`<span class="badge ${cls}">${esc(text)}</span>`;
const external=(url,text)=>safeUrl(url)?`<a href="${esc(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${text} ↗</a>`:'';
const avatar=p=>`<span class="avatar" aria-hidden="true">${esc((p?.name||'ТБ').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase())}</span>`;
const field=(label,name,value='',type='text',attrs='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const area=(label,name,value='',attrs='required')=>`<label class="field">${label}<textarea aria-label="${esc(label)}" name="${name}" maxlength="10000" ${attrs}>${esc(value)}</textarea></label>`;
const select=(label,name,options,value)=>`<label class="field">${label}<select aria-label="${esc(label)}" name="${name}">${options.map(x=>{const [v,t]=Array.isArray(x)?x:[x,x];return `<option value="${v}" ${String(value)===String(v)?'selected':''}>${t}</option>`}).join('')}</select></label>`;
const empty=(title,text,action='')=>`<div class="empty"><h2>${title}</h2><p>${text}</p>${action}</div>`;
const section=(title,content,action='')=>`<section class="section"><div class="section-head"><h2>${title}</h2>${action}</div>${content}</section>`;
const head=(title,sub='',action='')=>`<header><div><h1>${esc(title)}</h1>${sub?`<p class="muted">${sub}</p>`:''}</div><div class="actions">${action}</div></header>`;
const form=(type,id,body,extra='')=>`<form class="form" data-form="${type}" data-id="${esc(id)}" ${extra}>${body}</form>`;
const submit=(text,value='',cls='primary')=>`<button class="${cls}" ${value?`name="intent" value="${value}"`:''}>${text}</button>`;
const facts=items=>`<dl class="facts">${items.map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl>`;
function shell(){const r=route()[0],active={team:'messages',campaign:'campaigns',create:'campaigns',profile:'bloggers',compare:'bloggers',deal:role==='advertiser'?'campaigns':'projects','creator-profile':'creator-profile'}[r]||r;const notices=state.events.filter(e=>!e.read&&e.target===role&&(role==='advertiser'||e.personId===personId)).length;
 const nav=role==='advertiser'?[['overview','Главная'],['campaigns','Кампании'],['bloggers','Блогеры'],['saved','Сохраненные'],['messages','Сообщения']]:[['overview','Главная'],['requests','Заявки рекламодателей'],['projects','Сотрудничества'],['messages','Сообщения']];
 $('#sidebar').innerHTML=`<div class="sidebar-heading">${link('тутблогеры.рф','overview','brand')}<a class="notification-button ${r==='notifications'?'active':''}" href="#notifications" aria-label="Уведомления${notices?', непрочитанных: '+notices:''}" title="Уведомления">${icon('bell')}${notices?`<span class="notification-count">${notices}</span>`:''}</a></div>${role==='advertiser'?link(icon('plus')+'Создать кампанию','create','button primary create'):''}<nav aria-label="Основная навигация">${nav.map(([id,text])=>link(icon({requests:'campaigns',projects:'campaigns','creator-profile':'bloggers',notifications:'messages'}[id]||id)+text+(id==='notifications'&&notices?`<span class="count">${notices}</span>`:''),id,'nav '+(active===id?'active':''))).join('')}</nav><div class="bottom">${role==='blogger'?link(icon('bloggers')+'Мой профиль','creator-profile','nav profile-nav '+(active==='creator-profile'?'active':'')):link(icon('company')+'Профиль компании','company-profile','nav profile-nav '+(r==='company-profile'?'active':''))}${link('Помощь','help','nav')}<div class="profile-switch"><button class="account account-button" data-action="role-menu" aria-expanded="false" aria-controls="role-menu">${avatar(role==='advertiser'?state.company:person(personId))}<span>${esc(role==='advertiser'?state.company.name:person(personId).name)}<small>${role==='advertiser'?'Рекламодатель':'Блогер'}</small></span>${icon('arrow')}</button><div id="role-menu" class="role-menu" hidden><small>Кабинет</small>${button('Рекламодатель','switch','advertiser')}${button('Блогер','switch','blogger')}${role==='blogger'?select('Профиль','demoPerson',state.people.map(p=>[p.id,p.name]),personId):''}</div></div></div>`;
}
function overview(){
 const advertiser=role==='advertiser',name=advertiser?(state.company.contact||state.company.name):person(personId).name;
 const filter=route()[1]||'',all=[...tasks(),...waitingItems().map(t=>({...t,waiting:true}))].sort((a,b)=>Number(!!a.waiting)-Number(!!b.waiting)||homeTaskOrder(a,b)),ts=all.filter(t=>filter==='today'?t.timing==='today':filter==='overdue'?t.timing==='overdue':true),done=completedToday(),completed=ownDeals().filter(d=>d.status==='completed').length;
 const taskFilters=`<nav class="task-filters" aria-label="Фильтр задач">${[['','Все'],['today','Сегодня'],['overdue','Просрочено']].map(([id,label])=>link(label,'overview'+(id?'/'+id:''),'task-filter '+(id===filter?'active':''))).join('')}</nav>`;
 const donePanel=`<section class="home-side-panel home-done-panel"><h2>Сделано сегодня</h2>${done.length?`<ul class="home-done-list">${done.slice(0,5).map(item=>`<li><span class="home-done-check" aria-hidden="true">${homeCheckIcon()}</span><span>${link(esc(item.text),item.path)}${item.dealId&&dealById(item.dealId)?`<small>${esc(campaignById(dealById(item.dealId).campaignId).name)}</small>`:''}</span></li>`).join('')}</ul>${done.length>5?`<details><summary>Еще ${done.length-5}</summary><ul class="home-done-list">${done.slice(5).map(item=>`<li>${homeCheckIcon()}${link(esc(item.text),item.path)}</li>`).join('')}</ul></details>`:''}`:'<p class="muted">Здесь появятся выполненные вами действия.</p>'}</section>`;
 return `<div class="home-simple"><header class="home-greeting"><div><h1>${esc(name)}, привет!</h1></div></header><div class="home-workspace"><div class="home-main">${section('Задачи',taskFilters+(ts.length?`<div class="home-actions">${ts.slice(0,3).map(simpleActionCard).join('')}</div>${ts.length>3?`<details class="more-tasks"><summary>Еще</summary><div class="home-actions">${ts.slice(3).map(simpleActionCard).join('')}</div></details>`:''}`:`<div class="home-empty"><p>Сейчас нет задач, требующих вашего действия.</p>${link(advertiser?'Создать кампанию':'Посмотреть заявки',advertiser?'create':'requests','button')}</div>`))}${personalWorkSummary()}</div><aside class="home-aside" aria-label="Итоги дня и новости">${donePanel}<section class="home-side-panel"><h2>Новости проекта</h2><div class="home-news-item"><a href="#team" class="home-news-image" aria-label="Новости проекта"><img src="assets/news-wallpaper.png" alt="" width="320" height="130" loading="lazy"></a><strong>Обновление кабинета</strong><p>Задачи, ожидания и итоги дня собраны на главной.</p></div>${link('Все новости','team','home-side-link')}</section><div class="home-achievement-small"><strong>${completed}</strong><span>Завершено сотрудничеств</span>${link(advertiser?'К сотрудничествам':'Мой профиль',advertiser?'campaigns':'creator-profile')}</div></aside></div>${homePromo()}</div>`;
}
function homeTaskOrder(a,b){const rank={overdue:0,today:1,unscheduled:2,later:3};return (rank[a.timing]??2)-(rank[b.timing]??2)||(a.due&&b.due?a.due.localeCompare(b.due):0)||dashboardTaskRank(a)-dashboardTaskRank(b)}
function homeCheckIcon(){return '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="m5 12 4 4L19 6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>'}
function homeTaskTiming(item){if(!item.due)return '';return `<span class="home-stage-timing">${item.timing==='today'?badge('Сегодня','green'):(item.timing==='overdue'?badge('Просрочено','amber'):'')+'<span>Срок: '+shortHomeDate(item.due)+'</span>'}</span>`}
function homePromo(){
 if(role==='advertiser')return `<section class="home-promo"><div><h2>Следующая кампания начинается с автора</h2><p>В каталоге можно изучить профили и сравнить блогеров.</p></div>${link('Подобрать блогеров','bloggers','button')}</section>`;
 const open=state.campaigns.filter(c=>c.status==='active'&&c.request.status==='open'&&!c.request.applications.some(a=>a.personId===personId&&['pending','selected'].includes(a.status))&&!campaignDeals(c).some(d=>d.personId===personId&&participating(d))).length;
 return `<section class="home-promo"><div><h2>${open?'Открытые заявки для следующего проекта':'Посмотрите заявки рекламодателей'}</h2><p>${open?'Сейчас в прототипе доступны заявки: '+open+'. Изучите задачу и предложите свои условия.':'Бриф, сроки и условия собраны в каждой заявке.'}</p></div>${link('Посмотреть заявки','requests','button')}</section>`;
}
function shortHomeDate(day){if(!day)return '';const d=new Date(day+'T12:00:00'),months=['янв','фев','мар','апр','май','июн','июл','авг','сен','окт','ноя','дек'];return d.getDate()+' '+months[d.getMonth()]+(d.getFullYear()!==new Date(today()+'T12:00:00').getFullYear()?' '+d.getFullYear():'')}
function homeBrand(c){const categories={'ex-campaign-wardrobe':'Бренд одежды','ex-campaign-coffee':'Кофейня','ex-campaign-care':'Уходовая косметика','ex-campaign-weekend':'Туристический проект','ex-campaign-home':'Товары для дома','ex-campaign-city':'Городские аксессуары','ex-campaign-books':'Книжный проект','ex-campaign-studio':'Творческое пространство'};return (categories[c.id]||'Бренд')+' «'+(c.brand||state.company.name)+'»'}
function simpleActionCard(t){
 const parts=t.path.split('/'),d=t.dealId?dealById(t.dealId):parts[0]==='deal'?dealById(parts[1]):null,c=d?campaignById(d.campaignId):campaignById(parts[1]),terms=d?currentTerms(d):null,p=d&&t.placementId?d.placements.find(p=>p.id===t.placementId):null;
 if(!c)return '';
 const action=t.waiting?'Открыть':t.text.replace('Проверить неполучение оплаты','Уточнить оплату').replace('Подтвердить условия','Согласовать условия').replace('Проверить и отметить оплату','Отметить оплату');
 const fresh=d?.status==='negotiation'&&role==='blogger'?(d.source==='invitation'?'Приглашение':'Условия по отклику'):!d?'Новый отклик':'';
 return `<article class="home-action-card"><div class="home-card-top"><div><p class="home-brand">${esc(homeBrand(c))}${role==='advertiser'&&d?' · '+esc(person(d.personId).name):''}</p><h3>${link(esc(c.name),t.path)}</h3>${fresh?`<span class="home-card-kind">${fresh}</span>`:''}</div><div class="home-price"><strong>${money(terms?terms.price:c.budget)}</strong><small>${terms?'за сотрудничество':'бюджет кампании'}</small></div></div><div class="home-card-bottom"><div class="home-card-meta"><p>${esc((terms||c.brief).platform+' · '+(terms||c.brief).format)}${p?' · Размещение '+p.number:''}</p>${terms?`<span class="home-publication-date">Публикация ${shortHomeDate(terms.date)}</span>`:`<span>${esc(t.sub.split(' · ').slice(1).join(' · '))}</span>`}${t.waiting?`<span class="task-wait-status">${esc(t.text)}</span>`:''}${homeTaskTiming(t)}</div>${link(esc(action),t.path,'button '+(t.waiting?'':'primary ')+'home-action-button')}</div></article>`;
}
function simpleWaitingRow(item){
 const parts=item.path.split('/'),d=item.dealId?dealById(item.dealId):parts[0]==='deal'?dealById(parts[1]):null,c=d?campaignById(d.campaignId):campaignById(parts[1]),p=d?.placements.find(p=>p.id===item.placementId),detail=d?(role==='advertiser'?person(d.personId).name:(c.brand||'Рекламодатель'))+(p?' · Размещение '+p.number:''):'';
 return `<a class="home-wait-row" href="#${esc(item.path)}"><div class="home-wait-copy"><h3>${esc(c?.name||item.sub)}</h3><p>${esc(item.text)}</p>${detail?`<small>${esc(detail)}</small>`:''}${homeTaskTiming(item)}</div><span class="home-wait-arrow" aria-hidden="true">${icon('arrow')}</span></a>`;
}

function progressOf(d){const t=currentTerms(d),total=3+t.qty*(t.script?4:3);let done=(d.status==='completed'?1:0)+(t.approved.advertiser&&t.approved.blogger?1:0)+(d.payment.status==='confirmed'?1:0);for(const p of d.placements){if(t.script&&latest(p.scriptVersions)?.status==='approved')done++;if(latest(p.finalVersions)?.status==='approved')done++;if(p.publication?.status==='approved')done++;if(latest(p.statsVersions)?.status==='approved')done++;}return {done,total,percent:Math.round(done/total*100)}}
function widgetProgress(ds){const values=ds.map(progressOf),done=values.reduce((n,p)=>n+p.done,0),total=values.reduce((n,p)=>n+p.total,0);return total?`<div class="widget-progress-label"><span>Этапы выполнены</span><strong>${done} из ${total}</strong></div><div class="widget-progress" role="progressbar" aria-label="Выполнение этапов" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${done}"><span style="width:${Math.round(done/total*100)}%"></span></div>`:'<p class="muted">Подбор авторов · работа еще не началась</p>'}
function campaignWidget(c){const ds=campaignDeals(c).filter(participating),needs=tasks().filter(t=>t.path.includes(c.id)||ds.some(d=>t.path.includes(d.id))).length,published=ds.flatMap(d=>d.placements).filter(p=>p.publication?.status==='approved').length;return `<article class="dashboard-project"><div class="widget-top"><span>${esc(c.brand||state.company.name)}</span>${badge(needs?'Действий: '+needs:'В работе',needs?'purple':'')}</div><h3>${link(esc(c.name),'campaign/'+c.id)}</h3><p class="widget-date">${date(c.start)} — ${date(c.end)}</p>${widgetProgress(ds)}<div class="widget-footer"><span>Авторов: ${ds.length} из ${c.request.target} · Публикаций принято: ${published}</span>${link('К кампании →','campaign/'+c.id)}</div></article>`}
function collaborationWidget(d){const c=campaignById(d.campaignId),task=tasks().find(t=>t.path.includes(d.id)),p=d.placements.find(p=>latest(p.statsVersions)?.status!=='approved');return `<article class="dashboard-project"><div class="widget-top"><span>${esc(c.brand||'Рекламодатель')}</span>${badge(d.status==='negotiation'?'Условия':'В работе',d.status==='negotiation'?'purple':'')}</div><h3>${link(esc(c.name),'deal/'+d.id)}</h3><p class="widget-date">Публикация: ${date(currentTerms(d).date)}</p>${widgetProgress([d])}<p class="widget-next">${esc(task?task.text:d.status==='negotiation'?dealStatus(d):p?placementStatus(p,d):d.payment.status==='sent'?'Подтвердите получение оплаты':'Ожидаем завершения сотрудничества')}</p><div class="widget-footer"><span>${money(currentTerms(d).price)} · ${currentTerms(d).qty} размещ.</span>${link('Открыть →',task?.path||'deal/'+d.id)}</div></article>`}
function dashboardTask(t){return `<a class="dashboard-task" href="#${t.path}"><span><strong>${esc(t.text)}</strong><small>${esc(t.sub)}</small></span>${icon('arrow')}</a>`}
function dashboardWaiting(ds,ts){const waiting=ds.filter(d=>!ts.some(t=>t.path.includes(d.id)));return waiting.length?`<div class="dashboard-waiting">${waiting.slice(0,3).map(d=>`<a href="#deal/${d.id}"><strong>${esc(campaignById(d.campaignId).name)}</strong><small>${role==='advertiser'?esc(person(d.personId).name):esc(campaignById(d.campaignId).brand||'Рекламодатель')} · ${d.status==='negotiation'?esc(dealStatus(d)):role==='advertiser'?'Ждем блогера':'Ждем рекламодателя'}</small></a>`).join('')}</div>${waiting.length>3?link('Все сотрудничества →',role==='advertiser'?'campaigns':'projects'):''}`:'<p class="dashboard-quiet">Нет ожидающих ответов.</p>'}
function publicationAgenda(ds){const entries=ds.filter(d=>d.status==='active').flatMap(d=>d.placements.filter(p=>!p.publication).map(p=>({d,p,date:currentTerms(d).date}))).sort((a,b)=>a.date.localeCompare(b.date));return entries.length?`<div class="publication-agenda">${entries.slice(0,5).map(({d,p,date:day})=>`<a href="#deal/${d.id}/placement/${p.id}" class="agenda-entry"><time datetime="${day}"><strong>${new Date(day+'T12:00:00').getDate()}</strong><span>${new Date(day+'T12:00:00').toLocaleDateString('ru-RU',{month:'short'})}</span></time><span class="agenda-copy"><strong>${esc(campaignById(d.campaignId).name)}</strong><small>${esc(role==='advertiser'?person(d.personId).name:campaignById(d.campaignId).brand||'Рекламодатель')} · ${esc(currentTerms(d).format)} · Размещение ${p.number}</small></span>${day<today()?badge('Дата прошла','amber'):badge(day===today()?'Сегодня':date(day))}${icon('arrow')}</a>`).join('')}</div><p class="muted agenda-note">Плановые даты из согласованных условий. При переносе нужно обновить договоренность.</p>`:'<p class="dashboard-quiet">Нет публикаций, ожидающих выхода.</p>'}

function campaignRows(){return state.campaigns.length?`<div class="panel">${state.campaigns.map(c=>{const ds=campaignDeals(c),done=ds.filter(d=>d.status==='completed').length;return `<div class="row"><div class="grow"><h3>${link(esc(c.name),'campaign/'+c.id)}</h3><small>${date(c.start)} — ${date(c.end)} · ${money(c.budget)}</small></div>${badge(c.status==='cancelled'?'Отменена':c.status==='completed'?'Завершена':'В работе',c.status==='completed'?'green':'purple')}<span>${done} из ${ds.filter(participating).length} сотрудничеств завершено</span>${link('Открыть →','campaign/'+c.id)}</div>`}).join('')}</div>`:empty('Создайте первую кампанию','Соберите задачу, подборку авторов и результаты в одном месте.',link('Создать кампанию','create','button primary'))}
function campaignForm(){return head('Новая кампания')+form('campaign','',`<h2>Задача и бюджет</h2>${field('Название кампании','name','','text','required maxlength="80"')}${field('Название бренда','brand','','text','required maxlength="100"')}${field('Ссылка на продукт или сайт','site','','url')}${area('Продукт и цель кампании','product')}${field('Аудитория и география','audience','','text','required maxlength="300"')}<div class="form-grid">${field('Общий бюджет кампании, ₽','budget','','number','min="1" max="100000000" required')}${field('Количество блогеров','target',1,'number','min="1" max="100" required')}</div><div class="form-grid">${field('Начало кампании','start','','date','required')}${field('Окончание кампании','end','','date','required')}</div><h2>Бриф для блогеров</h2><div class="form-grid">${select('Площадка','platform',['VK','Telegram'],'VK')}${select('Формат','format',['Видео','Пост','Истории'],'Видео')}</div>${field('Размещений на одного блогера','qty',1,'number','min="1" max="10" required')}<div class="form-grid">${field('Оплата одному блогеру: от, ₽','priceMin',10000,'number','min="1" required')}${field('Оплата одному блогеру: до, ₽','priceMax',20000,'number','min="1" required')}</div><div class="form-grid video-fields">${select('Ориентация видео','orientation',[['','Не указана'],['vertical','Вертикальное 9:16'],['horizontal','Горизонтальное 16:9'],['square','Квадратное 1:1']],'')}${field('Длительность видео, сек.','duration','','number','min="1" max="3600"')}</div>${area('Состав работ','deliverables','Показать продукт в использовании.')}${area('Референсы: по одной ссылке на строку','refs','','')}${area('Требования к автору и контенту','requirements','Аудитория соответствует задаче кампании. Материал согласовывается до публикации.')}${area('Что предоставляет бренд','provides','Информация о продукте и материалы бренда. Условия передачи продукта согласуем отдельно.')}${area('Порядок и срок оплаты','payment','Оплата в течение 5 рабочих дней после приемки публикации.')}${field('Через сколько дней после публикации нужна статистика','statsDays',7,'number','min="1" max="90" required')}<label class="check"><input type="checkbox" name="script" checked>Сначала согласовать сценарий, затем готовый материал</label><div class="actions">${submit('Создать и опубликовать заявку','publish')}${submit('Сохранить черновик','draft','')}</div><p class="notice">Заявка нужна для открытого набора. Приглашать авторов из каталога можно и без публикации заявки.</p>`)}
function briefView(c){const b=c.brief;return facts([['Площадка и формат',esc(b.platform+' · '+b.format)],['Оплата одному блогеру',money(b.priceMin)+' — '+money(b.priceMax)],['Объем',esc(b.qty)+' размещ. на автора']])+`${c.site?`<p>${external(c.site,'Сайт бренда')}</p>`:''}<dl class="brief-list">${[['Бренд',c.brand||'Катрин · бренд'],['Задача',c.product],['Аудитория',c.audience],['Состав работ',b.deliverables],['Требования',b.requirements],['Бренд предоставляет',b.provides],['Оплата',b.payment],['Согласование',b.script?'Сценарий → готовый материал':'Готовый материал'],['Статистика','Через '+b.statsDays+' дней после публикации']].map(([k,v])=>`<div><dt>${k}</dt><dd class="brief-copy">${esc(v)}</dd></div>`).join('')}</dl>`}
function requestStatus(c){return {draft:'Не опубликована',open:'Набор открыт',closed:c.request.reason==='quota'?'Нужное число авторов выбрано':'Набор закрыт'}[c.request.status]}
function campaignView(c,tab='overview'){if(!c)return missing();const ds=campaignDeals(c),active=ds.filter(participating),placements=active.flatMap(d=>d.placements.map(p=>({d,p}))),confirmed=active.filter(d=>d.status!=='negotiation'),committed=confirmed.reduce((n,d)=>n+currentTerms(d).price,0),paid=active.filter(d=>d.payment.status==='confirmed').reduce((n,d)=>n+currentTerms(d).price,0);
 const top=link('← Кампании','campaigns','crumb')+head(c.name,'Кампания · '+date(c.start)+' — '+date(c.end),badge(c.status==='completed'?'Завершена':'В работе','purple'))+`<div class="tabs">${[['overview','Сводка'],['request','Заявка и отклики'],['bloggers','Подборка блогеров'],['collaborations','Сотрудничества'],['placements','Размещения'],['results','Результаты']].map(([v,t])=>link(t,'campaign/'+c.id+'/'+v,'tab '+(tab===v?'active':''))).join('')}</div>`;
 let content='';
 if(tab==='overview')content=facts([['Общий бюджет',money(c.budget)],['Согласовано с авторами',money(committed)],['Оплату подтвердили',money(paid)]])+ (committed>c.budget?'<div class="note">Согласованные расходы превышают бюджет кампании.</div>':'')+section('Поиск авторов',`<div class="actions">${link('Подобрать блогеров','bloggers/'+c.id,'button primary')}${link('Заявка и отклики','campaign/'+c.id+'/request','button')}</div><p>${requestStatus(c)} · Выбрано ${reserved(c)} из ${c.request.target} авторов</p>`)+section('Бриф кампании',briefView(c))+section('Завершение кампании',c.status==='cancelled'?'<p>Кампания отменена.</p>':c.status==='completed'?'<p>Все сотрудничества завершены. Кампания закрыта.</p>':active.length&&active.every(d=>d.status==='completed')&&c.request.status!=='open'?button('Завершить кампанию','complete-campaign',c.id,'primary'):'<p class="muted">Завершите сотрудничества и закройте набор. После этого здесь можно закрыть кампанию.</p>');
 if(tab==='request')content=section('Заявка для открытого набора',`<div class="actions">${badge(requestStatus(c),'purple')}${c.status==='completed'?'':c.request.status==='open'?button('Закрыть набор','close-request',c.id):c.request.status==='draft'?button('Опубликовать заявку','publish-request',c.id,'primary'):form('reopen',c.id,field('Всего нужно блогеров','target',Math.max(c.request.target,reserved(c)+1),'number',`min="${reserved(c)+1}" max="100" required`)+submit('Возобновить набор'))}</div><p class="muted">Выбрано ${reserved(c)} из ${c.request.target}. Место резервируется при отправке итоговых условий. При заполнении мест набор закрывается автоматически.</p>`)+section('Отклики',applicationRows(c))+section('Условия заявки',briefView(c));
 if(tab==='bloggers')content=section('Подборка',c.shortlist.length?`<div class="panel">${c.shortlist.map(pid=>{const p=person(pid),d=ds.find(d=>d.personId===pid&&participating(d));return `<div class="row">${avatar(p)}<div class="grow"><h3>${link(esc(p.name),'profile/'+p.id+'/'+c.id)}</h3><small>${esc(p.platform+' · '+p.topic)}</small></div>${d?link('Сотрудничество →','deal/'+d.id):!['completed','cancelled'].includes(c.status)?link('Пригласить','invite/'+c.id+'/'+p.id,'button primary'):''}</div>`}).join('')}</div>`:empty('Подборка пока пуста','Сравните авторов и сохраните подходящих в кампанию.'),!['completed','cancelled'].includes(c.status)?link('Добавить блогеров →','bloggers/'+c.id):'');
 if(tab==='collaborations')content=dealRows(ds);
 if(tab==='placements')content=placements.length?`<div class="panel">${placements.map(({d,p})=>`<div class="row"><div class="grow"><h3>${esc(person(d.personId).name)} · Размещение ${p.number}</h3><small>${date(currentTerms(d).date)} · ${esc(currentTerms(d).format)}</small></div>${badge(placementStatus(p,d),'purple')}${link('Открыть →','deal/'+d.id+'/placement/'+p.id)}</div>`).join('')}</div>`:empty('Пока нет размещений','Они появятся после подтверждения условий обеими сторонами.');
 if(tab==='results'){const accepted=placements.filter(({p})=>latest(p.statsVersions)?.status==='approved');content=facts([['Результаты приняты',accepted.length+' из '+placements.length],['Сумма просмотров',accepted.reduce((n,{p})=>n+latest(p.statsVersions).views,0).toLocaleString('ru-RU')],['Сумма реакций',accepted.reduce((n,{p})=>n+latest(p.statsVersions).reactions,0).toLocaleString('ru-RU')]])+`<p class="notice">Суммируются только принятые результаты. Просмотры разных публикаций не равны уникальному охвату. ${accepted.length<placements.length?'Отчет пока неполный.':''}</p>`+(placements.length?`<div class="panel table-wrap"><table class="results-table"><thead><tr><th>Размещение</th><th>Просмотры / реакции</th><th>Источник и период</th><th>Статус</th></tr></thead><tbody>${placements.map(({d,p})=>{const s=latest(p.statsVersions);return `<tr><td>${link(esc(person(d.personId).name)+' · '+p.number,'deal/'+d.id+'/placement/'+p.id)}</td><td data-label="Просмотры / реакции">${s?`${s.views} / ${s.reactions}`:'—'}</td><td data-label="Источник и период">${s?`${external(s.source,'Источник')}<br>${date(s.from)} — ${date(s.to)}<br><small>Внесено блогером · ${date(s.collected)}</small>`:'Ожидаем статистику'}</td><td data-label="Статус">${badge(s?{submitted:'На проверке',revision:'Нужно уточнение',approved:'Принято'}[s.status]:'Нет данных')}</td></tr>`}).join('')}</tbody></table></div>`:empty('Результатов пока нет','Здесь будет общая статистика размещений кампании.'));}
 return top+content+(c.status==='active'&&!ds.some(participating)?section('Управление кампанией',button('Отменить кампанию','cancel-campaign',c.id)): '');
}
function applicationRows(c){return c.request.applications.length?`<div class="panel">${c.request.applications.map(a=>{const p=person(a.personId);return `<div class="row">${avatar(p)}<div class="grow"><h3>${link(esc(p.name),'profile/'+p.id+'/'+c.id)}</h3><p class="brief-copy">${esc(a.text)}</p><small>${money(a.price)} · ${date(a.date)} · ${esc(a.scope)}</small></div><div class="actions">${a.status==='pending'?`${link('Согласовать условия','invite/'+c.id+'/'+p.id,'button primary')}${button('Отклонить','decline-application',c.id+':'+a.id)}`:badge({selected:'Перешли к условиям',declined:'Отклонен',withdrawn:'Отозван'}[a.status])}</div></div>`}).join('')}</div>`:empty('Пока нет откликов',c.request.status==='open'?'Заявка видна блогерам. Новые отклики появятся здесь и на главной.':'Опубликуйте заявку, чтобы получать отклики.')}
function profileCard(p,context){const saved=state.saved.includes(p.id),parts=p.audience.split(' · ');return `<article class="creator creator-compact"><div class="creator-heading">${avatar(p)}<div class="creator-identity"><h3>${link(esc(p.name),'profile/'+p.id+(context?'/'+context:''))}</h3><div class="creator-tags"><span>${esc(p.platform)}</span><span>${esc(p.topic)}</span></div></div><button class="bookmark-button ${saved?'is-saved':''}" data-action="save-person" data-id="${p.id}" aria-label="${saved?'Убрать из сохраненных':'Сохранить блогера'}: ${esc(p.name)}" aria-pressed="${saved}" title="${saved?'В сохраненных — нажмите, чтобы убрать':'Сохранить блогера в раздел «Сохраненные»'}">${icon('saved')}</button></div><div class="creator-audience"><span>Аудитория</span><p>${esc(parts.join(' · '))}</p></div><div class="stats"><div><strong>${esc(p.followers)}</strong><small>подписчиков</small></div><div><strong>${esc(p.views)}</strong><small>средние просмотры</small></div></div><p class="creator-price"><strong>От ${money(p.price)}</strong><span>за размещение</span></p><div class="creator-bottom">${link('Посмотреть профиль','profile/'+p.id+(context?'/'+context:''),'button profile-open')}<label class="check"><input type="checkbox" data-compare="${p.id}" ${selected.includes(p.id)?'checked':''}>Сравнить</label></div></article>`}

function catalogue(context,saved=false){const c=campaignById(context),list=state.people.filter(p=>(!saved||state.saved.includes(p.id))&&(!filters.q||(p.name+' '+p.topic+' '+p.audience).toLowerCase().includes(filters.q.toLowerCase()))&&(!filters.platform||p.platform===filters.platform)&&(!filters.topic||p.topic===filters.topic));return (c?link('← '+esc(c.name),'campaign/'+c.id+'/bloggers','crumb'):'')+head(saved?'Сохраненные блогеры':'Блогеры',c?'Подбор для кампании «'+esc(c.name)+'»':'Изучите аудиторию, примеры контента и условия авторов')+`<div class="filters"><input id="search" type="search" aria-label="Поиск блогеров" placeholder="Имя, тематика или город" value="${esc(filters.q)}">${select('Площадка','filterPlatform',['','VK','Telegram'].map(x=>[x,x||'Все площадки']),filters.platform)}${select('Тематика','filterTopic',['','Лайфстайл','Мода и стиль','Красота'].map(x=>[x,x||'Все тематики']),filters.topic)}${button('Сбросить','clear-filters','','text')}</div><p class="muted">Найдено: ${list.length}.</p>`+(list.length?`<div class="grid">${list.map(p=>profileCard(p,c?.id)).join('')}</div>`:empty('Нет подходящих авторов','Измените фильтры или поисковый запрос.'))+(selected.length?`<div class="comparebar"><span>Выбрано: ${selected.length} из 3</span>${link('Сравнить авторов','compare'+(context?'/'+context:''),'button')}</div>`:'')}
function profileView(p,context,own=false){if(!p)return missing();const ds=state.deals.filter(d=>d.personId===p.id),completed=ds.filter(d=>d.status==='completed').length,accepted=ds.flatMap(d=>d.placements).filter(p=>latest(p.statsVersions)?.status==='approved'),views=accepted.reduce((n,p)=>n+latest(p.statsVersions).views,0);const interests=(p.interests||p.topic+', Город, Локальные бренды').split(',').map(x=>x.trim()).filter(Boolean);const works=profileWorks(p),firstWork=ds.filter(d=>['active','completed'].includes(d.status)).flatMap(d=>d.terms.filter(t=>t.approved.advertiser&&t.approved.blogger).map(t=>t.at)).filter(Boolean).sort()[0],experienceYear=p.joinedAt?new Date(p.joinedAt).getFullYear():firstWork?new Date(firstWork).getFullYear():null;return (own?'':link('← '+(role==='advertiser'?(context?'К кампании':'Блогеры'):'Мой профиль'),role==='advertiser'?(context?'campaign/'+context+'/request':'bloggers'):'creator-profile','crumb'))+`<section class="profile-hero"><div class="profile-banner" aria-hidden="true"></div><div class="profile-identity">${avatar(p)}<div><h1>${esc(p.name)}</h1><p>${esc(p.platform+' · '+p.topic)}</p><small>${esc(p.audience)}</small></div><div class="actions">${own?link('Редактировать профиль','creator-profile/edit','button'):role==='advertiser'?link('Добавить в подборку','add/'+p.id+(context?'/'+context:''),'button primary'):link('Редактировать профиль','creator-profile/edit','button')}</div></div></section><div class="profile-layout"><div>${section('О себе',`<p class="brief-copy">${esc(p.bio)}</p><h3 class="interests-heading">Интересы</h3><div class="interest-tags">${interests.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`)}${facts([['Подписчики',esc(p.followers)],['Средние просмотры',esc(p.views)],['Цена от',money(p.price)]])}${section('Примеры работ',`<div class="work-gallery">${works.map((w,i)=>`<details class="work-card"><summary><span class="work-poster poster-${i%4}"><span class="work-format">${workTypeLabel(w.type)}</span>${icon('arrow')}</span><strong>${esc(w.title)}</strong><small>${esc(w.duration||'')}</small></summary><div class="work-description"><p>${esc(w.description)}</p>${external(w.url,'Посмотреть материал')}</div></details>`).join('')}</div>`)}${section('Форматы и условия',`<p>${esc(p.formats)}</p><p>${esc(p.availability)}</p>`)}${!own&&role==='advertiser'?button(state.saved.includes(p.id)?'Убрать из сохраненных':'Сохранить блогера','save-person',p.id):''}</div><aside class="profile-achievements">${section('Достижения',`<h3>В медиа</h3>${p.mediaAchievements?`<p class="brief-copy">${esc(p.mediaAchievements)}</p>`:'<p class="muted">Автор пока не добавил публикации и проекты.</p>'}<h3>На платформе</h3><div class="achievement-stats"><div><strong>${completed}</strong><span>Завершено сотрудничеств</span></div><div><strong>${accepted.length}</strong><span>Принятые размещения</span></div><div><strong>${views.toLocaleString('ru-RU')}</strong><span>просмотров в принятых отчетах</span></div></div>${completed?'<p class="achievement-note">'+approvalIcon(true)+' '+(experienceYear?(p.joinedAt?'На платформе с ':'Первое сотрудничество в ')+experienceYear+' году · ':'')+'Завершено: '+completed+'</p>':''}<p class="muted">Показатели по принятым результатам сотрудничеств.</p>`)}<div class="profile-contact"><h3>Для сотрудничества</h3><p>${esc(p.availability)}</p><strong>От ${money(p.price)}</strong></div></aside></div>`}
function profileWorks(p){if(p.gallery?.length>1)return p.gallery.filter(w=>w.title);const names=['Один день в городе','Знакомство с продуктом','Детали в кадре','Ответы на вопросы','Маршрут выходного дня','Любимые находки'];return names.map((title,i)=>({type:p.platform==='Telegram'?(i%2?'video':'post'):(i===3?'story':'video'),title,duration:p.platform==='Telegram'&&i%2===0?'':(25+i*5)+' сек.',description:i===0?p.portfolioText||'Авторский ролик.':'Авторская подача и детали продукта.',url:i===0?p.portfolio||'':''}));}
function workTypeLabel(type){return {story:'Истории',post:'Пост',video:'Видео',reel:'Видео'}[type]||'Материал'}
function workFields(w,i,p){return `<fieldset class="portfolio-editor"><legend>Материал ${i+1}</legend>${select('Формат','workType'+i,p.platform==='Telegram'?[['post','Пост'],['video','Видео']]:[['video','Видео'],['post','Пост'],['story','Истории']],w.type==='reel'?'video':w.type||'video')}${field('Название','workTitle'+i,w.title||'','text','maxlength="100"')}${field('Длительность или объем','workDuration'+i,w.duration||'')}${area('Описание','workDescription'+i,w.description||'','')}${field('Ссылка','workUrl'+i,w.url||'','url')}</fieldset>`}

function editProfile(){const p=person(personId);return head('Мой профиль','Данные для рекламодателей',link('Вернуться к профилю','creator-profile','button'))+form('profile',p.id,field('Имя','name',p.name,'text','required maxlength="80"')+area('О себе','bio',p.bio)+field('Интересы через запятую','interests',p.interests||p.topic+', Город, Локальные бренды','text','maxlength="300"')+area('Достижения в медиа','mediaAchievements',p.mediaAchievements||'','')+select('Тематика','topic',['Лайфстайл','Мода и стиль','Красота'],p.topic)+select('Основная площадка','platform',['VK','Telegram'],p.platform)+field('Аудитория и география','audience',p.audience,'text','required')+field('Форматы работы','formats',p.formats,'text','required')+field('Стоимость размещения от, ₽','price',p.price,'number','min="1" required')+field('Доступность для проектов','availability',p.availability,'text','required')+area('Описание примера работы','portfolioText',p.portfolioText)+field('Ссылка на пример работы','portfolio',p.portfolio,'url')+`<h2>Примеры работ</h2><div id="gallery-editor">${profileWorks(p).map((w,i)=>workFields(w,i,p)).join('')}</div><button type="button" data-action="gallery-add">Добавить работу</button>`+submit('Сохранить профиль'))}

function compareView(context){const ps=selected.map(person);return head('Сравнение блогеров','Сравните аудиторию и формат, затем откройте профиль автора')+(ps.length?`<div class="panel table-wrap"><table><thead><tr><th>Параметр</th>${ps.map(p=>`<th>${esc(p.name)}</th>`).join('')}</tr></thead><tbody>${[['platform','Площадка'],['topic','Тематика'],['audience','Аудитория'],['formats','Форматы'],['followers','Подписчики'],['views','Средние просмотры'],['price','Цена от']].map(([k,n])=>`<tr><th>${n}</th>${ps.map(p=>`<td>${k==='price'?money(p[k]):esc(p[k])}</td>`).join('')}</tr>`).join('')}<tr><th>Дальше</th>${ps.map(p=>`<td>${link('Посмотреть профиль','profile/'+p.id+(context?'/'+context:''))}</td>`).join('')}</tr></tbody></table></div><p class="notice">Цены разных форматов нельзя сравнивать напрямую.</p>`:empty('Сначала выберите авторов','Отметьте до трех блогеров в каталоге.',link('В каталог','bloggers')))}
function addView(pid,context){const p=person(pid);return head('Добавить в подборку',esc(p.name))+(state.campaigns.filter(c=>!['completed','cancelled'].includes(c.status)).length?form('shortlist',pid,select('Кампания','campaignId',state.campaigns.filter(c=>!['completed','cancelled'].includes(c.status)).map(c=>[c.id,c.name]),context)+submit('Добавить в подборку')+'<p class="muted">Автор попадет в подборку. Приглашение отправляется отдельно.</p>'):empty('Сначала создайте кампанию','После создания вернитесь к профилю автора.',link('Создать кампанию','create','button primary')))}
function requestList(){const list=state.campaigns.filter(c=>c.request.status==='open');const applied=state.campaigns.filter(c=>c.request.applications.some(a=>a.personId===personId));return head('Заявки рекламодателей','Изучите бриф и предложите свои условия')+section('Открытый набор',list.length?`<div class="panel">${list.map(c=>`<div class="row"><div class="grow"><h3>${link(esc(c.name),'requests/'+c.id)}</h3><p>${esc(c.product)}</p><small>${esc(c.brief.platform+' · '+c.brief.format)} · От ${money(c.brief.priceMin)} до ${money(c.brief.priceMax)} одному автору · ${date(c.start)} — ${date(c.end)}</small></div>${link('Посмотреть заявку →','requests/'+c.id)}</div>`).join('')}</div>`:empty('Открытых заявок пока нет','Здесь появятся опубликованные рекламодателями задачи.'))+section('Мои отклики',applied.length?`<div class="panel">${applied.map(c=>`<div class="row"><div class="grow"><h3>${link(esc(c.name),'requests/'+c.id)}</h3><small>${requestStatus(c)}</small></div>${badge({pending:'На рассмотрении',selected:'Согласование условий',declined:'Отклонен',withdrawn:'Отозван'}[c.request.applications.find(a=>a.personId===personId).status])}</div>`).join('')}</div>`:'<p class="muted">Вы еще не откликались.</p>')}
function requestView(c){if(!c)return missing();const a=c.request.applications.find(a=>a.personId===personId),d=campaignDeals(c).find(d=>d.personId===personId&&participating(d));return link('← Заявки','requests','crumb')+head(c.name,esc(c.brand||'Катрин · бренд'),badge(requestStatus(c),'purple'))+facts([['Период кампании',date(c.start)+' — '+date(c.end)],['Нужно авторов',c.request.target],['Общий бюджет кампании',money(c.budget)]])+briefView(c)+section('Ваш отклик',d?`<p>По этой кампании уже есть сотрудничество.</p>${link('Открыть условия →','deal/'+d.id)}`:a?`<p>${badge({pending:'Отклик на рассмотрении',selected:'Выбраны для согласования',declined:'Отклик отклонен',withdrawn:'Отклик отозван'}[a.status])}</p><p>${esc(a.text)}</p><p>${money(a.price)} · ${date(a.date)}</p>${a.status==='pending'?button('Отозвать отклик','withdraw-application',c.id):['withdrawn','declined'].includes(a.status)&&c.request.status==='open'?applyAgain(c,a):''}`:c.request.status!=='open'?'<p>Набор закрыт. Новые отклики не принимаются.</p>':form('apply',c.id,area('Почему вам подходит задача','text')+field('Предлагаемая стоимость за весь объем, ₽','price',person(personId).price,'number','min="1" required')+field('Предлагаемая дата публикации','date',c.start,'date',`min="${c.start}" max="${c.end}" required`)+area('Что входит в стоимость','scope',c.brief.deliverables)+submit('Отправить отклик')))}
function termsFields(t,c,d=null){return `<h3>Материал</h3><div class="form-grid">${select('Площадка','platform',['VK','Telegram'],t.platform)}${select('Формат','format',['Видео','Пост','Истории'],t.format)}</div><div class="form-grid video-fields">${select('Ориентация видео','orientation',[['','Не указана'],['vertical','Вертикальное 9:16'],['horizontal','Горизонтальное 16:9'],['square','Квадратное 1:1']],t.orientation||'')}${field('Длительность видео, сек.','duration',t.duration||'','number','min="1" max="3600"')}</div>${field('Количество размещений','qty',t.qty,'number','min="1" max="10" required')}${area('Состав работ','scope',t.scope)}${area('Референсы: по одной ссылке на строку','refs',Array.isArray(t.refs)?t.refs.join('\n'):t.refs||'','')}<h3>Сроки и согласование</h3><label class="check"><input name="script" type="checkbox" ${t.script?'checked':''}>Согласовать сценарий перед готовым материалом</label><div class="form-grid">${field('Сценарий до','scriptDue',t.scriptDue||'','date')}${field('Готовый материал до','finalDue',t.finalDue||'','date')}</div><div class="form-grid">${field('Ответ рекламодателя до','reviewDue',t.reviewDue||'','date')}${field('Публикация','date',t.date,'date',`min="${c.start}" max="${c.end}" required`)}</div><h3>Оплата</h3><div class="form-grid">${field('Стоимость сотрудничества, ₽','price',t.price,'number','min="1" required')}${field('Оплатить до','paymentDue',t.paymentDue||'','date')}</div>${select('Порядок оплаты','paymentMode',[['manual','По условиям'],['prepay','Предоплата'],['postpay','После публикации']],t.paymentMode||'manual')}${area('Порядок и срок оплаты','payment',t.payment)}<h3>Статистика</h3>${field('Через сколько дней после публикации','statsDays',t.statsDays,'number','min="1" max="90" required')}${d&&d.placements.length?placementPlanFields(t,c,d):''}`}

function inviteView(c,p){if(!c||!p)return missing();const a=c.request.applications.find(a=>a.personId===p.id&&a.status==='pending'),d=campaignDeals(c).find(d=>d.personId===p.id&&participating(d));if(d)return head('Уже есть сотрудничество')+link('Открыть →','deal/'+d.id);if(c.status==='completed'||reserved(c)>=c.request.target)return head('Все места заняты')+'<p>Увеличьте количество авторов в заявке, чтобы пригласить еще одного.</p>'+link('К заявке →','campaign/'+c.id+'/request');let t=briefTerms(c,p);if(a)Object.assign(t,{price:a.price,date:a.date,scope:a.scope});return link('← Кампания','campaign/'+c.id+'/bloggers','crumb')+head(a?'Итоговые условия по отклику':'Приглашение блогеру',esc(c.name+' · '+p.name))+`<h2 class="section">Условия сотрудничества</h2>`+form('invite',c.id,termsFields(t,c)+submit('Отправить условия блогеру')+'<p class="notice">Место в наборе будет зарезервировано. Работа начнется только после подтверждения блогером.</p>',`data-person="${p.id}"`)}
function dealRows(ds,filter=''){const ts=tasks(),all=ds,shown=ds.filter(d=>filter==='action'?ts.some(t=>t.dealId===d.id||t.path.includes(d.id)):filter==='active'?['active','negotiation'].includes(d.status):filter==='completed'?d.status==='completed':true);const tabs=role==='blogger'?`<nav class="tabs" aria-label="Фильтр сотрудничеств">${[['','Все'],['action','Требуют действия'],['active','В работе'],['completed','Завершены']].map(([id,label])=>link(label,'projects'+(id?'/'+id:''),'tab '+(filter===id?'active':''))).join('')}</nav>`:'';return tabs+(shown.length?`<div class="panel">${shown.map(d=>{const task=ts.find(t=>t.dealId===d.id||t.path.includes(d.id)),wait=typeof waitingItems==='function'?waitingItems().find(w=>w.dealId===d.id||w.d?.id===d.id||w.path?.includes(d.id)):null;return `<div class="row"><div class="grow"><h3>${link(esc(campaignById(d.campaignId).name),'deal/'+d.id)}</h3><small>${esc(role==='blogger'?(campaignById(d.campaignId).brand||'Рекламодатель'):person(d.personId).name)} · ${money(currentTerms(d).price)} · ${date(currentTerms(d).date)}</small><div class="deal-description-status">${badge(d.status==='negotiation'?(currentTerms(d).approved[role]?'Ожидаем вторую сторону':'Условия на согласовании'):dealStatus(d),d.status==='completed'?'green':'')}${!task&&wait?`<span>${esc(wait.text)}</span>`:''}</div></div>${link(task?esc(task.text):'Открыть',task?.path||'deal/'+d.id,task?'button primary':'button')}</div>`}).join('')}</div>`:empty(all.length?'Нет сотрудничеств в этом разделе':'Пока нет сотрудничеств',all.length?'Выберите другой фильтр.':role==='blogger'?'Откликнитесь на заявку или дождитесь приглашения.':'Добавьте блогера в кампанию и отправьте условия.'))}

function termsSummary(t){const refs=(Array.isArray(t.refs)?t.refs:String(t.refs||'').split(/\n/)).filter(Boolean);return `<div class="terms-sections"><section class="terms-part"><h3>Материал</h3>${facts([['Формат',termFormat(t)],['Объем',t.qty+' размещ.'],['Публикация',date(t.date)]])}<p class="brief-copy">${esc(t.scope)}</p>${refs.length?`<h4>Референсы</h4><ul>${refs.map((url,i)=>`<li>${external(url,'Референс '+(i+1))||esc(url)}</li>`).join('')}</ul>`:''}</section><section class="terms-part"><h3>Согласование</h3><p>${t.script?'Сценарий → готовый материал':'Готовый материал'}</p>${termDates(t,['scriptDue','finalDue','reviewDue'])}${(t.placementPlans||[]).length?`<h4>Сроки размещений</h4>${t.placementPlans.map((plan,i)=>`<div><strong>Размещение ${i+1}</strong><p>Публикация ${date(plan.plannedDate)}</p>${termDates(plan,['scriptDue','finalDue','reviewDue'])}</div>`).join('')}`:''}</section><section class="terms-part"><h3>Оплата</h3><p><strong>${money(t.price)}</strong> за сотрудничество</p><p class="brief-copy">${esc(t.payment)}</p>${t.paymentDue?`<p>Оплатить до ${date(t.paymentDue)}</p>`:''}</section><section class="terms-part"><h3>Статистика</h3><p>Через ${t.statsDays} дней после публикации</p></section></div>`}
function termFormat(t){return esc([t.platform,t.format,{vertical:'Вертикальное 9:16',horizontal:'Горизонтальное 16:9',square:'Квадратное 1:1'}[t.orientation],t.duration?'до '+t.duration+' сек.':''].filter(Boolean).join(' · '))}
function termDates(t,keys){const labels={scriptDue:'Сценарий до',finalDue:'Материал до',reviewDue:'Ответ до'};return keys.filter(k=>t[k]&&(k!=='scriptDue'||t.script)).map(k=>`<p>${labels[k]} ${date(t[k])}</p>`).join('')}
function compactTerms(t){return facts([['Стоимость',money(t.price)],['Публикация',date(t.date)],['Материал',termFormat(t)+' · '+t.qty+' размещ.']])}

function termsView(d){const t=currentTerms(d),c=campaignById(d.campaignId),pending=d.pendingTerms;let body=compactTerms(t)+button('Подробнее об условиях','deal-details',d.id,'text')+`<div class="term-approvals"><p>${approvalIcon(t.approved.advertiser)} ${t.approved.advertiser?'Рекламодатель подтвердил':'Ожидаем рекламодателя'}</p><p>${approvalIcon(t.approved.blogger)} ${t.approved.blogger?'Блогер подтвердил':'Ожидаем блогера'}</p></div>`;if(d.status==='negotiation')body+=`<div class="actions">${!t.approved[role]?button('Подтвердить условия','accept-terms',d.id,'primary'):''}${button('Отклонить условия','decline-terms',d.id)}</div>`;if(pending)body+=`<section class="pending-terms"><h3>Предложены изменения</h3>${compactTerms(pending)}${button('Подробнее об изменениях','deal-details',d.id+':pending','text')}<p>До подтверждения действуют прежние условия.</p>${pending.by!==role?`<div class="actions">${button('Принять изменения','accept-change',d.id,'primary')}${button('Отклонить изменения','reject-change',d.id)}</div>`:'<p class="muted">Ожидаем подтверждения второй стороны.</p>'}</section>`;if(['negotiation','active'].includes(d.status)&&!pending)body+=`<details class="section"><summary>Предложить изменения</summary>${form('terms',d.id,termsFields(t,c,d)+submit('Отправить условия'))}</details>`;if(d.terms.length>1)body+=`<details class="section"><summary>История условий (${d.terms.length})</summary>${d.terms.map((v,i)=>`<article class="version"><h3>Версия ${i+1}</h3><small>${stamp(v.at)}</small>${termsSummary(v)}</article>`).join('')}</details>`;return section('Условия',body)}

function dealView(d,view='',pid=''){if(!canSee(d))return missing();const c=campaignById(d.campaignId);const nav=link('← '+(role==='advertiser'?'Кампания':'Сотрудничества'),role==='advertiser'?'campaign/'+c.id+'/collaborations':'projects','crumb');let content='';if(view==='placement'){const p=d.placements.find(p=>p.id===pid);content=p?placementView(d,p):missing();}else if(view==='payment')content=paymentView(d);else if(view==='chat')content='';else content=termsView(d)+(d.status==='active'||d.status==='completed'?section('Размещения',`<div class="panel">${d.placements.map(p=>`<div class="row"><div class="grow"><h3>Размещение ${p.number}</h3><small>${termFormat(currentTerms(d))}${p.plannedDate?' · '+date(p.plannedDate):''}</small></div>${badge(placementStatus(p,d),'purple')}${link('Открыть размещение →','deal/'+d.id+'/placement/'+p.id)}</div>`).join('')}</div>`)+section('Оплата и завершение',`${link('Открыть учет оплаты →','deal/'+d.id+'/payment')}<p>${paymentLabel(d)}</p>${role==='advertiser'&&readyToComplete(d)?button('Завершить сотрудничество','complete-deal',d.id,'primary'):d.status==='completed'?badge('Сотрудничество завершено','green'):'<p class="muted">Для завершения нужны приемка всех размещений и статистики, а также подтверждение получения оплаты.</p>'}`):'');return nav+head(c.name,esc(role==='blogger'?(c.brand||'Катрин · бренд'):person(d.personId).name)+' · '+dealStatus(d),role==='advertiser'?link('Профиль блогера','profile/'+d.personId+'/'+c.id,'button'):'')+(view?link('← Все сотрудничество','deal/'+d.id,'crumb'):'')+content+(view==='chat'?section('Переписка',chatView(d)):chatPreview(d))+dealProblems(d)+`<details class="section"><summary>История сотрудничества</summary>${d.history.map(h=>`<p><small>${stamp(h.at)}</small> · ${esc(h.text)}</p>`).join('')}</details>`}
function materialBlock(d,p,kind){const versions=kind==='script'?p.scriptVersions:p.finalVersions,v=latest(versions),title=kind==='script'?'Сценарий':'Готовый материал',allowed=d.status==='active'&&(kind==='script'||!currentTerms(d).script||latest(p.scriptVersions)?.status==='approved');
 let body=v?`<article class="version"><h3>Версия ${versions.length} ${badge({submitted:'На согласовании',revision:'Нужны правки',approved:'Согласовано'}[v.status],'purple')}</h3><small>${stamp(v.at)}</small><p class="brief-copy">${esc(v.text)}</p>${external(v.url,'Открыть материал')}${v.feedback?`<div class="note"><strong>Комментарий рекламодателя</strong><p>${esc(v.feedback)}</p></div>`:''}</article>`:'<p class="muted">Пока не отправлен.</p>';
 if(!allowed&&kind==='final'&&d.status==='active')body+='<p class="note">Сначала согласуйте сценарий.</p>';
 if(allowed&&role==='blogger'&&(!v||v.status==='revision'))body+=form('material',d.id,area(kind==='script'?'Текст сценария':'Описание готового материала','text',v?.text||'')+field(kind==='script'?'Ссылка на сценарий (необязательно)':'Ссылка на готовый материал','url',v?.url||'','url',kind==='final'?'required':'')+submit(kind==='script'?'Отправить сценарий':'Отправить готовый материал'),`data-placement="${p.id}" data-kind="${kind}"`);
 if(allowed&&role==='advertiser'&&v?.status==='submitted')body+=form('review-material',d.id,area('Комментарий','feedback','','')+`<div class="actions">${submit('Согласовать','approved')}${submit('На доработку','revision','')}</div>`,`data-placement="${p.id}" data-kind="${kind}"`);
 if(versions.length>1)body+=`<details class="section"><summary>Предыдущие версии (${versions.length-1})</summary><div class="version-comparison">${versions.slice(0,-1).map((v,i)=>`<article class="version"><h3>Версия ${i+1}</h3><small>${stamp(v.at)}</small><p class="brief-copy">${esc(v.text)}</p>${external(v.url,'Материал')}<p><strong>Комментарий:</strong> ${esc(v.feedback||'Без замечаний')}</p></article>`).join('')}</div></details>`;
 return `<section class="section"><details class="material-stage" ${allowed&&v?.status!=='approved'?'open':''}><summary>${title} ${v?badge({submitted:'На согласовании',revision:'Нужны правки',approved:'Согласовано'}[v.status],v.status==='approved'?'green':'purple'):badge(allowed?'Ожидает материал':'После сценария')}</summary>${body}</details></section>`;
}
function placementView(d,p){const active=d.status==='active',f=latest(p.finalVersions),s=latest(p.statsVersions),pub=p.publication;let body=`<header><div><h2>Размещение ${p.number}</h2><p class="muted">${esc(placementStatus(p,d))}</p></div></header>`+`<ol class="workflow">${(currentTerms(d).script?['Сценарий']:[]).concat(['Материал','Публикация','Статистика','Приемка']).map(t=>`<li>${t}</li>`).join('')}</ol>`+(currentTerms(d).script?materialBlock(d,p,'script'):'')+materialBlock(d,p,'final');
 body+=section('Учет маркировки',p.mark?`<p>erid: <strong>${esc(p.mark.erid)}</strong> · ${esc(p.mark.advertiser)}</p><small>Запись добавлена ${stamp(p.mark.at)}. Подлинность не проверена.</small>`:'<p class="muted">Данные маркировки пока не внесены.</p>');
 if(active)body+=`<details><summary>${p.mark?'Изменить запись':'Добавить данные маркировки'}</summary>${form('mark',d.id,field('Идентификатор erid','erid',p.mark?.erid||'','text','required maxlength="150"')+field('Рекламодатель','advertiser',p.mark?.advertiser||'','text','required maxlength="150"')+submit('Сохранить запись'),`data-placement="${p.id}"`)}</details>`;
 body+='';
 let publication=pub?`${external(pub.url,'Открыть публикацию')}<p>Опубликовано автором: ${date(pub.date)} · ${badge({submitted:'Ссылка добавлена — ждем проверки',approved:'Публикация принята',revision:'Нужны исправления'}[pub.status],'purple')}</p>${pub.feedback?`<div class="note">${esc(pub.feedback)}</div>`:''}`:'<p class="muted">Ссылка пока не добавлена.</p>';
 if(active&&f?.status==='approved'&&role==='blogger'&&(!pub||pub.status==='revision'))publication+=form('publication',d.id,field('Ссылка на публикацию','url',pub?.url||'','url','required')+field('Фактическая дата публикации','date',pub?.date||today(),'date','required')+submit('Отправить ссылку на проверку'),`data-placement="${p.id}"`);
 else if(!pub&&f?.status!=='approved')publication+='<p class="note">Добавить ссылку можно после согласования готового материала.</p>';
 if(active&&role==='advertiser'&&pub?.status==='submitted')publication+=form('review-publication',d.id,area('Комментарий к публикации','feedback','','')+`<div class="actions">${submit('Подтвердить публикацию','approved')}${submit('Запросить исправление','revision','')}</div>`,`data-placement="${p.id}"`);
 if(p.publicationHistory.length)publication+=`<details><summary>Предыдущие ссылки и замечания</summary>${p.publicationHistory.map(x=>`<p>${external(x.url,'Публикация')} · ${esc(x.feedback||'Без комментария')}</p>`).join('')}</details>`;
 body+=section('Публикация',publication);
 let stats=s?facts([['Просмотры',s.views],['Реакции',s.reactions],['Статус',{submitted:'На проверке',revision:'Нужно уточнение',approved:'Результат принят'}[s.status]]])+`<p>Период: ${date(s.from)} — ${date(s.to)}. Собрано ${date(s.collected)}.</p><p>${external(s.source,'Подтверждение статистики')} · Внесено блогером</p>${s.feedback?`<div class="note">${esc(s.feedback)}</div>`:''}`:'<p class="muted">Статистика пока не добавлена.</p>';
 if(active&&role==='blogger'&&pub?.status==='approved'&&statsDue(p,d)>today()&&!s)stats+=`<p class="note">Статистика будет нужна ${date(statsDue(p,d))}.</p>`;
 if(active&&role==='blogger'&&pub?.status==='approved'&&statsDue(p,d)<=today()&&(!s||s.status==='revision'))stats+=form('stats',d.id,`<p>Передайте статистику через ${currentTerms(d).statsDays} дней после публикации.</p><div class="form-grid">${field('Просмотры','views',s?.views??'','number','min="0" step="1" required')}${field('Реакции','reactions',s?.reactions??'','number','min="0" step="1" required')}</div><div class="form-grid">${field('Начало периода','from',s?.from||pub.date,'date','required')}${field('Конец периода','to',s?.to||today(),'date','required')}</div>${field('Дата сбора статистики','collected',s?.collected||today(),'date','required')}${field('Ссылка на статистику или скриншот','source',s?.source||'','url','required')}${submit('Отправить статистику')}`,`data-placement="${p.id}"`);
 if(active&&role==='advertiser'&&s?.status==='submitted')stats+=form('review-stats',d.id,area('Комментарий к статистике','feedback','','')+`<div class="actions">${submit('Принять результат','approved')}${submit('Запросить уточнение','revision','')}</div>`,`data-placement="${p.id}"`);
 if(p.statsVersions.length>1)stats+=`<details><summary>История статистики</summary>${p.statsVersions.slice(0,-1).map(x=>`<p>${x.views} просмотров · ${x.reactions} реакций · ${esc(x.feedback||'Без замечаний')} · ${external(x.source,'Источник')}</p>`).join('')}</details>`;
 body+=section('Статистика и приемка',stats);return body;
}
function paymentLabel(d){return {unmarked:'Оплата еще не отмечена',sent:'Рекламодатель отметил оплату — ждем подтверждения блогера',confirmed:'Получение оплаты подтверждено',disputed:'Блогер сообщил: оплата не поступила'}[d.payment.status]}
function paymentView(d){const t=currentTerms(d);let body=facts([['Сумма',money(t.price)],['Срок',t.paymentDue?date(t.paymentDue):'По условиям'],['Статус',paymentLabel(d)]])+`<p class="brief-copy">${esc(t.payment)}</p><p class="notice">${role==='advertiser'?'Оплатите напрямую и отметьте платеж. Блогер подтвердит получение.':'После отметки рекламодателя подтвердите получение оплаты.'}</p>`;if(d.payment.reference)body+=`<p>Комментарий: ${esc(d.payment.reference)} · ${date(d.payment.date)}</p>`;
 if(d.status==='active'&&role==='advertiser'&&['unmarked','disputed'].includes(d.payment.status))body+=form('payment',d.id,field('Дата внешней оплаты','date',today(),'date','required')+field('Комментарий или номер платежа','reference','','text','required maxlength="200"')+submit('Отметить оплату вне платформы'));
 if(d.status==='active'&&role==='blogger'&&d.payment.status==='sent')body+=`<div class="actions">${button('Подтвердить оплату','confirm-payment',d.id,'primary')}${button('Оплата не поступила','dispute-payment',d.id)}</div>`;
 if(d.paymentHistory?.length)body+=`<details><summary>История отметок оплаты</summary>${d.paymentHistory.map(x=>`<p>${esc({unmarked:'Оплата не отмечена',sent:'Отправка отмечена',confirmed:'Получение подтверждено',disputed:'Оплата не поступила'}[x.status]||x.status)}${x.date?' · '+date(x.date):''}${x.reference?' · '+esc(x.reference):''}</p>`).join('')}</details>`;return section('Оплата',body);
}
function chatView(d){return `<div class="chat"><div class="chat-toolbar"><span>${esc(role==='blogger'?campaignById(d.campaignId).brand||'Рекламодатель':person(d.personId).name)}</span>${button('Сообщить о проблеме','open-issue',d.id,'text')}</div><div class="chat-history">${d.chat.length?d.chat.map(m=>`<div class="bubble ${m.role===role?'mine':''}"><strong>${m.role===role?'Вы':m.role==='advertiser'?'Рекламодатель':'Блогер'}</strong><p class="brief-copy">${esc(m.text)}</p><small>${stamp(m.at)}</small></div>`).join(''):'<p class="muted">Обсудите детали сотрудничества.</p>'}</div>${form('chat',d.id,area('Сообщение','text','','required maxlength="2000"')+submit('Отправить'))}</div>`}
function chatPreview(d){const m=d.chat.at(-1);return section('Переписка',`<div class="chat-preview">${m?`<p class="message-preview">${esc((m.role===role?'Вы: ':'')+m.text)}</p>`:'<p class="muted">Сообщений пока нет.</p>'}${link('Открыть переписку','deal/'+d.id+'/chat','button')}</div>`)}
function dealProblems(d){const cr=d.cancelRequest;return `<section class="section deal-problems" id="deal-issue"><details><summary>Сообщить о проблеме</summary><p class="muted">Обращение сохранится в этом прототипе. Отправки в службу поддержки пока нет.</p>${form('issue',d.id,select('Причина','reason',['Условия сотрудничества','Материал или публикация','Оплата','Другое'],'Условия сотрудничества')+area('Что произошло','text')+submit('Сохранить обращение'))}${(d.issues||[]).map(i=>`<article class="version"><h3>${esc(i.reason)}</h3><p>${esc(i.text)}</p><small>${date(i.at.slice(0,10))} · ${i.status==='closed'?'Закрыто':'Открыто'}</small>${i.by===role&&i.status==='open'?button('Закрыть обращение','close-issue',d.id+':'+i.id,'text'):''}</article>`).join('')}</details>${d.status==='active'?`<details class="section"><summary>Отмена сотрудничества</summary>${cr?.status==='pending'?`<p>${esc(cr.reason)}</p>${cr.by!==role?`<div class="actions">${button('Согласовать отмену','accept-cancel',d.id)}${button('Продолжить сотрудничество','reject-cancel',d.id)}</div>`:'<p class="muted">Ожидаем ответа на запрос отмены.</p>'}`:form('cancel-request',d.id,area('Причина отмены','reason')+submit('Предложить отмену'))}</details>`:''}</section>`}

function notifications(){const es=state.events.filter(e=>e.target===role&&(role==='advertiser'||e.personId===personId));return head('Уведомления','',button('Отметить прочитанными','read-events'))+(es.length?`<div class="panel">${es.map(e=>`<div class="row"><div class="grow"><h3>${link(esc(e.text),e.path)}</h3><small>${stamp(e.at)}</small></div>${!e.read?badge('Новое','purple'):''}</div>`).join('')}</div>`:empty('Уведомлений пока нет','Здесь появятся отклики, изменения условий и материалы.'))}
function help(){return head('Помощь')+`<div class="reading"><h2>Как устроена работа</h2><p><strong>Кампания</strong> — общая рекламная задача, бюджет и подбор блогеров.</p><p><strong>Сотрудничество</strong> — работа с одним блогером: условия, материалы, публикации и оплата.</p><p><strong>Размещение</strong> — отдельная публикация со своими материалами и статистикой.</p><h2>Как начать</h2><p>${role==='advertiser'?'Создайте кампанию. Опубликуйте заявку или добавьте авторов из каталога в подборку. Затем отправьте условия сотрудничества.':'Изучите заявки рекламодателей и отправьте отклик. Если вас пригласили, проверьте и согласуйте условия.'}</p><h2>Как проходит сотрудничество</h2><p>Согласуйте условия и материалы. После публикации добавьте ссылку и статистику. Оплата проходит напрямую: рекламодатель отмечает отправку, блогер подтверждает получение.</p><h2>Если возникла проблема</h2><p>Откройте сотрудничество и выберите «Сообщить о проблеме». Изменение условий и отмена требуют согласия второй стороны.</p></div>`}

function missing(){return head('Страница недоступна')+link('Вернуться на главную','overview')}

function applyAgain(c,a){return `<details class="section"><summary>Изменить и отправить повторно</summary>${form('apply',c.id,area('Почему вам подходит задача','text',a.text)+field('Предлагаемая стоимость за весь объем, ₽','price',a.price,'number','min="1" required')+field('Предлагаемая дата публикации','date',a.date,'date',`min="${c.start}" max="${c.end}" required`)+area('Что входит в стоимость','scope',a.scope)+submit('Отправить отклик'))}</details>`}
function messagesView(){
 const filter=route()[1]||'',all=conversationRows(),rows=filter==='unread'?all.filter(x=>x.unread):all,unread=all.reduce((n,x)=>n+x.unread,0),total=all.reduce((n,x)=>n+x.incoming,0);
 return head('Сообщения')+`<div class="inbox-layout"><div class="inbox-main"><nav class="task-filters" aria-label="Фильтр сообщений">${link('Все','messages','task-filter '+(!filter?'active':''))}${link('Непрочитанные','messages/unread','task-filter '+(filter==='unread'?'active':''))}</nav><div class="panel inbox-list">${rows.length?rows.map(x=>`<a class="inbox-row ${x.id==='team'?'inbox-pinned':''}" href="#${x.path}">${avatar({name:x.name})}<div class="inbox-copy"><div class="inbox-title"><strong>${esc(x.name)}</strong>${x.id==='team'?'<span class="pinned-label">Закреплено</span>':''}</div>${x.context?`<small>${esc(x.context)}</small>`:''}<p>${esc(x.preview)}</p></div><div class="inbox-meta"><time>${stamp(x.at)}</time>${x.unread?`<span class="unread-dot" aria-label="Непрочитанных сообщений: ${x.unread}">${x.unread}</span>`:''}</div></a>`).join(''):'<p class="inbox-empty">Непрочитанных сообщений нет.</p>'}</div></div><aside class="inbox-tools" aria-label="Управление сообщениями"><h2>Входящие</h2><dl><div><dt>Непрочитано</dt><dd>${unread}</dd></div><div><dt>Прочитано</dt><dd>${total-unread}</dd></div></dl>${button('Отметить прочитанными','read-conversations','','text')}<p class="muted">Статусы относятся к входящим сообщениям.</p></aside></div>`;
}

function waitingView(){const rows=ownDeals().filter(d=>d.status==='negotiation'?currentTerms(d).approved[role]:d.status==='active'&&!tasks().some(t=>t.path.includes(d.id)));return rows.length?section('Ожидаете ответа',`<div class="panel">${rows.map(d=>`<div class="row"><div class="grow"><h3>${esc(campaignById(d.campaignId).name)}</h3><small>${d.status==='negotiation'?esc(dealStatus(d)):role==='advertiser'?'Ждем блогера':'Ждем рекламодателя'}</small></div>${link('Открыть →','deal/'+d.id)}</div>`).join('')}</div>`):''}

function taskRow(t){return `<div class="row"><div class="grow"><h3>${esc(t.text)}</h3><small>${esc(t.sub)}</small></div>${link("Открыть →",t.path)}</div>`}

function companyProfile(edit=false){const c=state.company;if(edit)return head('Редактировать компанию','',link('К профилю компании','company-profile','button'))+form('company','',field('Название компании','name',c.name,'text','required maxlength="100"')+field('Сфера деятельности','industry',c.industry,'text','required maxlength="150"')+area('О компании','description',c.description)+field('Сайт компании','site',c.site,'url')+field('Контактное лицо','contact',c.contact,'text','required maxlength="100"')+field('Телефон менеджера','phone',c.phone||'','tel','maxlength="30"')+field('Рабочая почта','email',c.email,'email')+`<h2>Юридическая информация</h2>`+select('Форма организации','legalType',[['','Не указана'],['ООО','ООО'],['ИП','ИП']],c.legalType||'')+field('Полное наименование ООО или ФИО ИП','legalName',c.legalName||'','text','maxlength="200"')+field('ИНН','inn',c.inn||'','text','inputmode="numeric" maxlength="12"')+field('ОГРН / ОГРНИП','ogrn',c.ogrn||'','text','inputmode="numeric" maxlength="15"')+submit('Сохранить компанию'));const active=state.campaigns.filter(c=>c.status==='active').length,completed=state.campaigns.filter(c=>c.status==='completed').length;return `<section class="profile-hero"><div class="profile-banner" aria-hidden="true"></div><div class="profile-identity">${avatar(c)}<div><h1>${esc(c.name)}</h1><p>${esc(c.industry)}</p></div><div class="actions">${link('Редактировать компанию','company-profile/edit','button')}</div></div></section><div class="split"><div>${section('О компании',`<p class="brief-copy">${esc(c.description)}</p>`)}${facts([['Активные кампании',active],['Завершенные кампании',completed],['Сотрудничества с авторами',state.deals.filter(d=>d.status==='completed').length]])}${link('Перейти к кампаниям','campaigns','button')}${companyWorksView()}</div><div>${section('Контакты',`<dl class="company-contact-list"><div><dt>Менеджер</dt><dd>${esc(c.contact)}</dd></div><div><dt>Телефон менеджера</dt><dd>${esc(c.phone||'Не указан')}</dd></div>${c.email?`<div><dt>Почта</dt><dd>${external('mailto:'+c.email,'')||`<a href="mailto:${esc(c.email)}">${esc(c.email)}</a>`}</dd></div>`:''}${c.site?`<div><dt>Сайт</dt><dd>${external(c.site,'Сайт компании')}</dd></div>`:''}</dl>`)}${section('Юридическая информация',`<dl class="company-contact-list"><div><dt>${c.legalType==='ИП'?'Индивидуальный предприниматель':'Юридическое лицо'}</dt><dd>${esc(c.legalName||'Не указано')}</dd></div><div><dt>ИНН</dt><dd>${esc(c.inn||'Не указан')}</dd></div><div><dt>${c.legalType==='ИП'?'ОГРНИП':'ОГРН'}</dt><dd>${esc(c.ogrn||'Не указан')}</dd></div></dl>`)}</div></div>`}

function dashboardTaskRank(t){return /Исправить|Уточнить|неполучение/.test(t.text)?0:/Проверить|Подтвердить|Завершить/.test(t.text)?1:2}

function personalWorkSummary(){const ds=ownDeals().filter(d=>['active','completed'].includes(d.status)&&currentTerms(d).approved.advertiser&&currentTerms(d).approved.blogger),received=ds.filter(d=>d.payment.status==='confirmed').reduce((n,d)=>n+currentTerms(d).price,0),remaining=ds.filter(d=>d.payment.status!=='confirmed').reduce((n,d)=>n+currentTerms(d).price,0),completed=ds.filter(d=>d.status==='completed').length,active=ds.filter(d=>d.status==='active').length,advertiser=role==='advertiser';return `<section class="personal-work-summary" aria-label="${advertiser?'Итоги работы компании':'Мои итоги работы'}"><div class="personal-total"><strong>${money(received)}</strong><span>${advertiser?'Оплату подтвердили':'Получено'}</span></div><div class="personal-total"><strong>${money(remaining)}</strong><span>${advertiser?'Осталось по условиям':'Ожидается по условиям'}</span></div><div class="personal-track"><p><strong>${active}</strong> в работе <span aria-hidden="true">·</span> <strong>${completed}</strong> завершено</p>${link(advertiser?'Мои кампании →':'Мои сотрудничества →',advertiser?'campaigns':'projects')}</div></section>`}

function approvalIcon(approved){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true">${approved?'<path d="m5 12 4 4L19 6"/>':'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'}</svg>`}
function placementPlanFields(t,c,d){return `<h3>Сроки отдельных размещений</h3>${d.placements.map((p,i)=>{const plan=t.placementPlans?.find(x=>x.id===p.id)||p;return `<fieldset><legend>Размещение ${p.number||i+1}</legend>${field('Публикация','plannedDate_'+p.id,plan.plannedDate||t.date,'date',`min="${c.start}" max="${c.end}" required`)}<div class="form-grid">${field('Сценарий до','scriptDue_'+p.id,plan.scriptDue||t.scriptDue||'','date')}${field('Материал до','finalDue_'+p.id,plan.finalDue||t.finalDue||'','date')}</div>${field('Ответ до','reviewDue_'+p.id,plan.reviewDue||t.reviewDue||'','date')}</fieldset>`}).join('')}`}

function companyWorkSources(){return state.deals.filter(d=>!['cancelled','declined'].includes(d.status)&&currentTerms(d).format==='Видео').flatMap(d=>d.placements.filter(p=>p.publication?.status==='approved'&&latest(p.finalVersions)?.status==='approved').map(p=>({id:d.id+':'+p.id,title:campaignById(d.campaignId).name,author:person(d.personId).name,url:p.publication.url,repostUrl:''})));}
function companyWorkItems(){return state.company.works||[];}
function companyWorksView(){const items=companyWorkItems(),sources=companyWorkSources();return section('Сотрудничество с блогерами',items.length?`<div class="company-video-gallery">${items.map((w,i)=>`<article class="company-video-card ${w.orientation==='horizontal'?'landscape':'portrait'}">${w.mediaId?`<video class="company-video" data-local-video="${esc(w.mediaId)}" controls playsinline preload="none" aria-label="${esc(w.title)}"></video><p class="video-load-status muted" data-video-status="${esc(w.mediaId)}">Загрузка видео…</p>`:/\.(mp4|webm)(\?|$)/i.test(w.url||'')?`<video class="company-video" src="${esc(safeUrl(w.url))}" controls playsinline preload="none" aria-label="${esc(w.title)}"></video>`:`<div class="company-video legacy-video"><p>Видео не загружено</p>${external(w.url,'Открыть публикацию')}</div>`}<h3>${esc(w.title)}</h3><p class="company-video-author">${esc(w.author)}</p><details><summary>Информация</summary>${w.url?`<p>${external(w.url,'Публикация блогера')}</p>`:''}${w.repostUrl?`<p>${external(w.repostUrl,'Публикация компании')}</p>`:''}${form('company-repost',w.id,field('Ссылка на публикацию компании','repostUrl',w.repostUrl||'','url','required')+submit('Сохранить ссылку'))}${button('Убрать из профиля','remove-company-video',w.id,'text')}</details></article>`).join('')}</div>`:'<p class="muted">Здесь будут видео блогеров, которые компания добавила в свой профиль.</p>')+`<details class="section"><summary>Добавить видео</summary>${form('company-work','',select('Связать с сотрудничеством','source',[['','Без привязки'],...sources.map(w=>[w.id,w.author+' · '+w.title])],'')+field('Название ролика','title','','text','maxlength="100"')+field('Блогер','author','','text','maxlength="100"')+select('Формат видео','orientation',[['vertical','Вертикальное · 9:16'],['horizontal','Горизонтальное · 16:9']],'vertical')+`<label class="field">Видеофайл<input type="file" name="videoFile" accept="video/mp4,video/webm" required></label><p class="muted">MP4 или WebM, до 100 МБ. Видео сохраняется в этом браузере.</p>`+field('Ссылка на публикацию компании (необязательно)','repostUrl','','url')+submit('Добавить в профиль'))}</details>`;}
